/**
 * 插件侧运行时（薄层）。
 *
 * 命令分流、宿主命令白名单、插件状态读写、native 回落、合成事件——这些**全部**在
 * 宿主注入运行时里（`src/platform/runtime/otools/invoke-routing.ts` +
 * `embedded-runtime.js`）。SDK 这里只做三件事：
 *
 * 1. `invoke` 转发 `window.otools.invoke`（实现只有一份，不分叉）；
 * 2. 保留 Tauri 事件原语（`listenTauri` / `invokeTauri`），那是 webview 自带能力，
 *    不算业务实现，也是移植 Tauri 插件时最常用的 shim；
 * 3. `openPath` / `openExternal` 转发宿主注入的 shell 能力。
 */

import type { OToolsAPI } from './otools-globals';

export interface Event<T> {
  event: string;
  id: number;
  payload: T;
}

export type UnlistenFn = () => Promise<void> | void;

export type EventTarget =
  | { kind: 'Any' | 'AnyLabel'; label?: string }
  | { kind: 'Window' | 'Webview' | 'WebviewWindow'; label: string };

export interface ListenOptions {
  target?: string | EventTarget;
}

const TAURI_LISTEN_TARGET = { kind: 'Any' } as const;

/** 宿主注入的 API；老宿主可能没有该字段。 */
export const getOtoolsApi = (): OToolsAPI | undefined => {
  if (typeof window === 'undefined') {
    return undefined;
  }
  return window.otools ?? (window as unknown as { utools?: OToolsAPI }).utools;
};

/** 是否跑在 OTools 插件 webview 里（注入 API 是否存在）。 */
export const isOtoolsPluginRuntime = (): boolean => Boolean(getOtoolsApi());

const getTauriInternals = () =>
  typeof window === 'undefined' ? undefined : window.__TAURI_INTERNALS__;

const normalizeTauriCallbackPayload = <T>(payload: unknown): T => {
  if (payload && typeof payload === 'object' && 'payload' in (payload as Record<string, unknown>)) {
    return (payload as { payload: T }).payload;
  }
  return payload as T;
};

/** 直接走 Tauri 通道（不经过宿主分流）；移植老插件时的逃生口。 */
export async function invokeTauri<T = unknown>(
  command: string,
  payload?: unknown,
): Promise<T> {
  const internals = getTauriInternals();
  if (!internals?.invoke) {
    throw new Error('Tauri runtime is unavailable');
  }
  return internals.invoke<T>(command, payload as Record<string, unknown> | undefined);
}

/**
 * 通用命令通道。
 *
 * 实现只有一份：宿主注入运行时的 `window.otools.invoke`（apiVersion >= 2），
 * 它内部已经做了「宿主命令 / 插件 native cdylib / 旧命令别名」的分流。
 */
export async function invoke<T = unknown>(
  command: string,
  payload?: Record<string, unknown>,
): Promise<T> {
  const api = getOtoolsApi();
  if (typeof api?.invoke !== 'function') {
    throw new Error('宿主未提供 otools.invoke（需要 apiVersion >= 2）');
  }
  return api.invoke<T>(command, payload);
}

/** Tauri 事件订阅原语（webview 自带能力，不是宿主业务逻辑）。 */
export async function listenTauri<T>(
  event: string,
  handler: (event: Event<T>) => void | Promise<void>,
  options: ListenOptions = {},
): Promise<UnlistenFn> {
  const internals = getTauriInternals();
  if (!internals?.invoke || !internals.transformCallback) {
    throw new Error('Tauri event runtime is unavailable');
  }

  let active = true;
  const handlerId = internals.transformCallback((payload) => {
    if (!active) return;
    void handler({
      event,
      id: payload && typeof payload === 'object' && 'id' in payload ? Number(payload.id) : -1,
      payload: normalizeTauriCallbackPayload<T>(payload),
    });
  }, false);

  let eventId: number;
  try {
    eventId = await internals.invoke<number>('plugin:event|listen', {
      event,
      target:
        typeof options.target === 'string'
          ? { kind: 'AnyLabel', label: options.target }
          : options.target ?? TAURI_LISTEN_TARGET,
      handler: handlerId,
    });
  } catch (error) {
    internals.unregisterCallback?.(handlerId);
    throw error;
  }

  return async () => {
    if (!active) return;
    active = false;
    try {
      await window.__TAURI_EVENT_PLUGIN_INTERNALS__?.unregisterListener?.(event, eventId);
    } catch {
      // 下面的后端 unlisten 仍会清掉服务端监听。
    }
    internals.unregisterCallback?.(handlerId);
    await internals.invoke('plugin:event|unlisten', { event, eventId });
  };
}

/** 订阅 Tauri 事件。 */
export async function listen<T>(
  event: string,
  handler: (event: Event<T>) => void | Promise<void>,
  options: ListenOptions = {},
): Promise<UnlistenFn> {
  return listenTauri<T>(event, handler, options);
}

/** 发 Tauri 事件（宿主侧同样监听这条事件总线）。 */
export async function emit<T = unknown>(event: string, payload?: T): Promise<void> {
  await invokeTauri('plugin:event|emit', { event, payload: payload ?? null });
}

/** 用系统默认程序打开链接。 */
export function openExternal(url: string): boolean {
  const api = getOtoolsApi();
  if (!api || typeof api.shellOpenExternal !== 'function') {
    return false;
  }
  api.shellOpenExternal(url);
  return true;
}

/** 用系统默认程序打开路径。 */
export function openPath(fullPath: string): boolean {
  const api = getOtoolsApi();
  if (!api || typeof api.openPath !== 'function') {
    return false;
  }
  return api.openPath(fullPath);
}
